import { Table, ReferenceColumn, StringColumn, IntegerColumn, DateTimeColumn, GuidColumn } from '@servicenow/sdk/core'

export const sys_email_attachment = Table({
    allowWebServiceAccess: true,
    label: 'Email Attachment',
    name: 'sys_email_attachment',
    schema: {
        email: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            cascadeRule: 'delete',
            label: 'Email',
            referenceTable: 'sys_email',
        }),
        source: StringColumn({
            dropdown: 'dropdown_with_none',
            label: 'Source',
        }),
        sys_updated_by: StringColumn({
            label: [
                {
                    label: 'Updated by',
                    plural: 'Updated by',
                    language: 'en',
                },
            ],
        }),
        action: StringColumn({
            dropdown: 'dropdown_with_none',
            label: 'Action',
        }),
        sys_created_by: StringColumn({
            label: [
                {
                    label: 'Created by',
                    plural: 'Created by',
                    language: 'en',
                },
            ],
        }),
        sys_mod_count: IntegerColumn({
            label: [
                {
                    label: 'Updates',
                    plural: 'Updates',
                    language: 'en',
                },
            ],
        }),
        action_reason: StringColumn({
            label: [
                {
                    hint: 'Action performed when processing the attachment',
                    label: 'Action Reason',
                    plural: 'Action Reasons',
                    language: 'en',
                },
            ],
            maxLength: 100,
        }),
        sys_created_on: DateTimeColumn({
            label: [
                {
                    label: 'Created',
                    plural: 'Created',
                    language: 'en',
                },
            ],
        }),
        attachment: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            cascadeRule: 'delete',
            label: 'Attachment',
            referenceTable: 'sys_attachment',
        }),
        file_name: StringColumn({
            label: 'File Name',
            maxLength: 100,
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        content_disposition: StringColumn({
            dropdown: 'dropdown_with_none',
            label: [
                {
                    hint: 'Specifies whether the attachment was displayed inline or as an attachment in the email',
                    label: 'Content Disposition',
                    plural: 'Content Dispositions',
                    language: 'en',
                },
            ],
        }),
        sys_updated_on: DateTimeColumn({
            label: [
                {
                    label: 'Updated',
                    plural: 'Updated',
                    language: 'en',
                },
            ],
        }),
    },
})
